def count_components(graph):
    n = len(graph)
    visited = [False] * n
    count = 0
    for start in range(n):
        if visited[start]:
            continue
        count += 1
        stack = [start]
        visited[start] = True
        while stack:
            u = stack.pop()
            for v in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)
    return count

print(count_components([[1], [0, 2], [1], [], [5], [4]]))
print(count_components([]))
print(count_components([[], [], [], []]))

